from pysat.solvers import Glucose3
from pysat.card import *

# Social Golfers: 32 golfers, 8 groups of 4, 7 weeks
# Variables: x[w][p][g] = True if golfer p is in group g in week w
# w in 0..6, p in 0..31, g in 0..7

num_weeks = 7
num_golfers = 32
num_groups = 8
group_size = 4

# Create variable mapping: var(w, p, g) -> integer
def var(w, p, g):
    return w * num_golfers * num_groups + p * num_groups + g + 1

num_vars = num_weeks * num_golfers * num_groups

solver = Glucose3()

# Constraint 1: Each golfer is in exactly one group each week
for w in range(num_weeks):
    for p in range(num_golfers):
        # At least one group
        solver.add_clause([var(w, p, g) for g in range(num_groups)])
        # At most one group (pairwise)
        for g1 in range(num_groups):
            for g2 in range(g1+1, num_groups):
                solver.add_clause([-var(w, p, g1), -var(w, p, g2)])

# Constraint 2: Each group has exactly 4 golfers each week
for w in range(num_weeks):
    for g in range(num_groups):
        # At least 4 golfers - use cardinality constraint
        # At most 4 golfers
        # Use CardEnc for exact cardinality
        lits = [var(w, p, g) for p in range(num_golfers)]
        # Exactly 4
        cnf = CardEnc.equals(lits, bound=group_size, encoding=EncType.pairwise)
        for clause in cnf.clauses:
            solver.add_clause(clause)

# Constraint 3: No pair of golfers in same group more than once
for p1 in range(num_golfers):
    for p2 in range(p1+1, num_golfers):
        for w1 in range(num_weeks):
            for w2 in range(w1+1, num_weeks):
                for g in range(num_groups):
                    # Not both in group g in week w1 AND week w2
                    solver.add_clause([-var(w1, p1, g), -var(w1, p2, g), -var(w2, p1, g), -var(w2, p2, g)])

print("Solving...")
if solver.solve():
    model = solver.get_model()
    print("SAT!")

    # Extract solution
    solution = [0] * (num_weeks * num_golfers)
    for w in range(num_weeks):
        for p in range(num_golfers):
            for g in range(num_groups):
                v = var(w, p, g)
                if v in model:
                    solution[w * num_golfers + p] = g

    print("Solution:", solution)
else:
    print("UNSAT")

solver.delete()

