import itertools

def solve_sgp(num_groups, group_size, num_weeks):
    num_golfers = num_groups * group_size

    def var(w, p, g):
        return w * num_golfers * num_groups + p * num_groups + g + 1

    num_vars = num_weeks * num_golfers * num_groups

    solver = Glucose3()

    # Each golfer in exactly one group each week
    for w in range(num_weeks):
        for p in range(num_golfers):
            solver.add_clause([var(w, p, g) for g in range(num_groups)])
            for g1 in range(num_groups):
                for g2 in range(g1+1, num_groups):
                    solver.add_clause([-var(w, p, g1), -var(w, p, g2)])

    # Each group has exactly group_size golfers
    for w in range(num_weeks):
        for g in range(num_groups):
            for combo in itertools.combinations(range(num_golfers), group_size+1):
                solver.add_clause([-var(w, p, g) for p in combo])
            lits = [var(w, p, g) for p in range(num_golfers)]
            cnf = CardEnc.atleast(lits, bound=group_size, encoding=EncType.seqcounter)
            for clause in cnf.clauses:
                solver.add_clause(clause)

    # No pair in same group more than once
    for p1 in range(num_golfers):
        for p2 in range(p1+1, num_golfers):
            for w1 in range(num_weeks):
                for w2 in range(w1+1, num_weeks):
                    for g in range(num_groups):
                        solver.add_clause([-var(w1, p1, g), -var(w1, p2, g), -var(w2, p1, g), -var(w2, p2, g)])

    if solver.solve():
        model = solver.get_model()
        solution = [0] * (num_weeks * num_golfers)
        for w in range(num_weeks):
            for p in range(num_golfers):
                for g in range(num_groups):
                    v = var(w, p, g)
                    if v in model:
                        solution[w * num_golfers + p] = g
        solver.delete()
        return solution
    else:
        solver.delete()
        return None

